F(shop, "public static final java.util.concurrent.ConcurrentHashMap VOID = new java.util.concurrent.ConcurrentHashMap();")
F(shop, "public static volatile int FAIL_NEXT = 0;")   # HARNESS SEAM ONLY (0 in game): the next n shop writes fail before writing
