        HSet = JClass("java.util.HashSet")

        @JImplements("java.util.function.Function")
        class CFn(object):
            def __init__(self, f):
                self.f = f

            @JOverride
            def apply(self, a):
                return self.f(a)
        _cs_src = open(os.path.join(ROOT, "SkyyCoins", "build_skyycoins_0.1.11.py"), encoding="utf8").read()
        CVT = re.search(r"^CURVE_TEXT = '([0-9.:,]+)'", _cs_src, re.M).group(1)
        CVP = [(int(a_), float(c_)) for a_, c_ in (kv.split(":") for kv in CVT.split(","))]

        def p7c(lv):
            x = max(1, min(100, lv))
            if x >= CVP[-1][0]:
                (x0, y0), (x1, y1) = CVP[-2], CVP[-1]
            else:
                for (x0, y0), (x1, y1) in zip(CVP, CVP[1:]):
                    if x0 <= x <= x1:
                        break
            return _m.exp(_m.log(y0) + (_m.log(y1) - _m.log(y0)) * (x - x0) / float(x1 - x0))

        def p7r(x):
            if not x > 0:
                return 0
            st_ = 10 if x < 1000 else (100 if x < 10000 else (500 if x < 100000 else 5000))
            return int(st_ * _m.floor(x / st_ + 0.5))

        def refp(lv, n, hours=0.25, hour=8333, free=10, curve=True):
            return p7r(hours * max(1, n - free) * hour * (p7c(lv) if curve else 1.0))
        cfg0 = (int(Cfg.FREE), int(Cfg.MAX), str(Cfg.BYLEVEL))
        Cfg.FREE = 10
