        sf = os.path.join(Wd, "requip", kC, "shop.json")
        good_ = open(sf, "rb").read()
        for bad_b, what_ in ((b"{not json", "unreadable"), (b'{"format": 2, "bought": 1}', "a newer format"), (b'{"format": 1, "bought": 1, "pending": {"n": 3}}', "a broken note")):
            open(sf, "wb").write(bad_b)
            restart()
            clv["lv"] = 90
            t_ = cb()
            rS = str(run(Pc, 18, 12, "1"))
            rR = str(run(Pc, 4, 0, "Main"))
            K.check(bool(cdata().shopBad) and eqbind()[0] == "eq" and "- buy" not in t_ and rS.startswith("-Your bought slots could not be read") and open(sf, "rb").read() == bad_b
                    and rR.startswith("+") and not cdata().bad, "CS13 shop.json %s: purchases shut, never written over (not even the peak), Requip itself works (%s / %s)" % (what_, rS, rR))
        open(sf, "wb").write(good_)
        restart()
        K.check(int(cdata().bought) == 8 and not bool(cdata().shopBad), "CS13 the good file back: 8 bought slots again")
        # ---- CS14 rollback safety: the files 0.2.11 reads keep their format; no item moved for any purchase
        ix_ = json.load(open(os.path.join(Wd, "requip", kC, "index.json")))
        K.check(jv_(ix_["format"]) == 2 and "bought" not in json.dumps(ix_) and "bought" not in open(os.path.join(Wd, "requip", kC, "loadouts.json")).read(),
                "CS14 index.json format 2 and loadouts.json carry no shop field (0.2.11 reads them; shop.json is its own file)")
        K.check(not [1 for c_ in Pc.secs for i_ in range(int(c_.getCapacity())) if c_.getItemStack(JShort(i_)) is not None] and len(cdata().entries) == 0,
                "CS14 no item appeared, moved or vanished for any purchase")
        # ---- CS15 (fix round) SkyyCoins' flush answer, VOID notes, the watcher's profile race, the default slots.byLevel
        Pf = W.player("00000000-0000-0000-0000-0000000000c8", "Fixer")
        uF, kF = str(Pf.u), str(Store.pkey(Pf.u))
        clv["lv"] = 10
        Shop.LASTBUY.clear()

        def fshop():
            f_ = os.path.join(Wd, "requip", kF, "shop.json")
            return json.load(open(f_)) if os.path.isfile(f_) else None

        def fdata():
            return Store.get(kF, Pf.u)

        def flreset(fails):
            coins["fl"] = 0
            coins["flfail"] = set(fails)
        q11, q12 = refp(10, 11), refp(10, 12)
        coins["bal"][uF] = 100000
        coins["calls"][:] = []
        flreset([1])
        rX1 = str(run(Pf, 18, 10, str(q11)))
        K.check(rX1.startswith("-Your coins could not be saved just now") and not ncalls("take") and coins["bal"][uF] == 100000
                and (fshop() is None or "pending" not in fshop()) and int(fdata().bought) == 0,
                "CS15 fix b: SkyyCoins' flush fails BEFORE the purse is read: refused, no note, no take (%s)" % rX1)
        Shop.LASTBUY.clear()
        coins["calls"][:] = []
        flreset([2])
        rX2 = str(run(Pf, 18, 10, str(q11)))
        K.check(rX2 == "-Your coins could not be saved - nothing changed (your %s coins are back)." % "{:,}".format(q11) and ncalls("take") == [("take", uF, q11)]
                and ncalls("add") == [("add", uF, q11)] and coins["bal"][uF] == 100000 and int(fdata().bought) == 0 and "pending" not in fshop()
                and any(" BUYFAIL " in l_ and "not saved by SkyyCoins - refunded" in l_ for l_ in rqlog()),
                "CS15 fix b: the flush after the take answers -1: the EXACT coins back, nothing unlocked, the note cleared, BUYFAIL (%s)" % rX2)
        Shop.LASTBUY.clear()
        coins["calls"][:] = []
        coins["add_ok"] = False
        flreset([2])
        rX3 = str(run(Pf, 18, 10, str(q11)))
        coins["add_ok"] = True
        flreset([])
        K.check(rX3.startswith("+Loadout 11 is open - paid") and coins["bal"][uF] == 100000 - q11 and int(fdata().bought) == 1 and "pending" not in fshop(),
                "CS15 fix b: the flush fails AND the refund fails: the coins are gone in SkyyCoins' memory -> the slot opens (never paid without it) (%s)" % rX3)
        Shop.LASTBUY.clear()
        b_ = coins["bal"][uF]
        coins["take_ok"] = False
        Shop.FAIL_SKIP, Shop.FAIL_NEXT = 1, 1
        rX4 = str(run(Pf, 18, 11, str(q12)))
        coins["take_ok"] = True
        sjv = fshop()
        K.check(rX4 == "-Not enough coins - nothing changed." and sjv.get("pending") is not None and str(Shop.VOID.get(kF)) == str(jv_(sjv["pending"]["tx"]))
                and int(fdata().bought) == 1, "CS15 fix a: take FALSE and the note cannot be cleared: the note stays on disk, VOID in memory (%s / %s)" % (rX4, sjv))
        coins["bal"][uF] = b_ + 50   # the purse moves for another reason before the check
        rS_ = Shop.settle(Pf.u, fdata())
        K.check(rS_ is None and int(fdata().bought) == 1 and "pending" not in fshop() and Shop.VOID.get(kF) is None and coins["bal"][uF] == b_ + 50
                and any(" BUYFIX " in l_ and "void note cleared" in l_ for l_ in rqlog()),
                "CS15 fix a: ... the next check clears the void note although the purse changed: nothing unlocked, no free slot (%s)" % rS_)
        Shop.LASTBUY.clear()
        b_ = coins["bal"][uF]
        Shop.FAIL_SKIP, Shop.FAIL_NEXT = 1, 2
        rX5 = str(run(Pf, 18, 11, str(q12)))
        K.check(rX5 == "-Could not save the new slot - your %s coins were given back." % "{:,}".format(q12) and coins["bal"][uF] == b_
                and fshop().get("pending") is not None and Shop.VOID.get(kF) is not None and int(fdata().bought) == 1,
                "CS15 fix a: refunded and the note cannot be cleared: VOID (%s)" % rX5)
        coins["bal"][uF] = b_ + 50
        Shop.watch(Pf.u)
        K.check(int(fdata().bought) == 1 and "pending" not in fshop() and Shop.VOID.get(kF) is None and coins["bal"][uF] == b_ + 50,
                "CS15 fix a: ... the 30 s watch clears the void note: nothing unlocked (refunded = not owed)")
        p0_ = int(fdata().peak)

        def s_level_sw(a):
            state.setdefault("key", {})[uF] = uF + "-p2"   # a profile switch lands between the watcher's key read and its level read
            return JIntC2.valueOf(77)
        br.put("skill:fn:level", CFn(s_level_sw))
        Shop.watch(Pf.u)
        br.put("skill:fn:level", CFn(s_level))
        del state["key"][uF]
        K.check(p0_ == 10 and int(fdata().peak) == 10 and jv_(fshop()["peak"]) == 10,
                "CS15 fix c: a profile switch during the watch: the other profile's level is NOT written into this profile's peak (%s)" % fshop())
        clv["lv"] = 77
        Shop.watch(Pf.u)
        K.check(jv_(fshop()["peak"]) == 77, "CS15 fix c: ... the next watch on the same profile saves its own level (%s)" % fshop())
        clv["lv"] = 61
        # the default slots.byLevel (a QUESTION for Skyy: it still opens 15 - 18 free at Overall Level 30 / 40); the lock texts
        Pl = W.player("00000000-0000-0000-0000-0000000000c9", "Leveled")
        kL = str(Store.pkey(Pl.u))
        ov0 = state.get("overall")
        Cfg.BYLEVEL = "6:10,10:20,14:30,18:40"
        state["overall"] = 30
        clv["lv"] = 10
        dL = Store.get(kL, Pl.u)
        pgl = TP(Pl.pr)
        pgl.handleDataEvent(Pl.ref, Pl.st, json.dumps({"a": "ls", "i": "14", "t": str(pgl.tok)}))
        bl_, evl_ = UCB(), UEB()
        pgl.build(Pl.ref, bl_, evl_, Pl.st)
        ml_ = " ".join(str(c.data if c.data is not None else c.text) for c in list(bl_.getCommands()) if c.selector is not None and str(c.selector) == "#SkyyRqEq.Text")
        K.check(int(Slots.unlocked(Pl.u, dL)) == 14 and int(Shop.next(Pl.u, dL)) == 14 and int(Shop.quote(Pl.pr, Pl.st, Pl.ref, dL, 14)) == refp(10, 15)
                and ("Buy slot 15 - %s coins" % "{:,}".format(refp(10, 15))) in ml_ and str(Shop.lockHint(dL, 15, 14)) == "buy loadout 15 first, or Overall Level 40",
                "CS15 default slots.byLevel at Overall Level 30: 14 open, slot 15 = the Buy card at the 5-step price, card 16 'buy loadout 15 first, or Overall Level 40' (%s / %s)" % (ml_, Shop.lockHint(dL, 15, 14)))
        state["overall"] = 40
        K.check(int(Slots.unlocked(Pl.u, dL)) == 18 and int(Shop.next(Pl.u, dL)) == -1, "CS15 ... Overall Level 40: all 18 open by level, nothing to buy (kept: a question for Skyy)")
        Cfg.BYLEVEL = "-"
        if ov0 is None:
            state.pop("overall", None)
        else:
            state["overall"] = ov0
        lt_ = str(Slots.lockText(12))
        coins_on(False)
        lt0_ = str(Slots.lockText(12))
        coins_on()
        K.check(lt_ == "locked - buy the loadouts before it first" and lt0_ == "locked - an admin can open it",
                "CS15 fix d: slots.byLevel - and buying on: a locked card points at buying; without SkyyCoins it stays 'an admin can open it' (%s / %s)" % (lt_, lt0_))
        clv["lv"] = 61
        # back to the harness defaults
        coins_on(False)
        br.remove("skill:fn:level")
        Cfg.FREE, Cfg.MAX, Cfg.BYLEVEL = cfg0[0], cfg0[1], cfg0[2]
        Shop.LASTBUY.clear()
        P("CfgPub").flush()

